package mcp

import (
	"net/url"
	"strings"
	"testing"
)

// Regression coverage for the MCP path-escaping guard
// (formatMCPPathParamValue in tools.go): path-bound MCP arguments must never
// smuggle slashes, dot segments, backslashes, or query characters into the
// request path, and must round-trip through PathUnescape unchanged.
func TestFormatMCPPathParamValueEscapesHostileInput(t *testing.T) {
	cases := []struct {
		name  string
		input any
	}{
		{name: "plain company", input: "leverdemo"},
		{name: "slash", input: "a/b"},
		{name: "traversal", input: "../secret"},
		{name: "deep traversal", input: "../../../etc/passwd"},
		{name: "encoded traversal", input: "..%2F..%2Fetc"},
		{name: "backslash", input: `..\..\windows`},
		{name: "query chars", input: "a?b&c=d"},
		{name: "hash and space", input: "a b#c"},
		{name: "unicode", input: "café-東京"},
		{name: "empty", input: ""},
		{name: "non-string", input: 42},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := formatMCPPathParamValue(tc.input)
			if strings.Contains(got, "/") {
				t.Fatalf("escaped value %q contains a raw slash (path-segment smuggling)", got)
			}
			back, err := url.PathUnescape(got)
			if err != nil {
				t.Fatalf("escaped value %q does not unescape: %v", got, err)
			}
			if want := formatMCPParamValue(tc.input); back != want {
				t.Fatalf("round-trip mismatch: escaped %q unescapes to %q, want %q", got, back, want)
			}
		})
	}
}
